import "server-only";
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { env } from "./env";

/**
 * Where uploaded files live. Local disk now; an S3-compatible provider can
 * implement the same interface later without touching callers.
 */
export interface StorageProvider {
  put(key: string, bytes: Uint8Array): Promise<void>;
  get(key: string): Promise<Buffer | null>;
  delete(key: string): Promise<void>;
}

/** Keys are generated by the server only; this rejects anything path-like anyway. */
const KEY = /^[a-zA-Z0-9_-]+\/[a-zA-Z0-9_-]+\.(png|jpg|webp)$/;

class LocalDiskStorage implements StorageProvider {
  constructor(private readonly root: string) {}

  private file(key: string): string {
    if (!KEY.test(key)) throw new Error("Invalid storage key.");
    return path.join(this.root, key);
  }

  async put(key: string, bytes: Uint8Array) {
    const f = this.file(key);
    await mkdir(path.dirname(f), { recursive: true });
    await writeFile(f, bytes, { flag: "wx" }); // never overwrite
  }

  async get(key: string) {
    try {
      return await readFile(this.file(key));
    } catch (e) {
      if ((e as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw e;
    }
  }

  async delete(key: string) {
    await rm(this.file(key), { force: true });
  }
}

export const storage: StorageProvider = new LocalDiskStorage(path.resolve(env.STORAGE_DIR ?? path.join(process.cwd(), "storage")));
